1	#!/usr/bin/env node
2	import { TextDecoder } from "node:util";
3	
4	const decoder = new TextDecoder("utf-8", { fatal: true });
5	const START = "<!-- skill-rails-next:verify-records:start -->";
6	const END = "<!-- skill-rails-next:verify-records:end -->";
7	const RECORD_PREFIX = "<!-- skill-rails-next:verify-record:";
8	
9	function compareCodePoint(a, b) {
10	  const left = Array.from(a); const right = Array.from(b);
11	  for (let index = 0; index < Math.min(left.length, right.length); index += 1) { const difference = left[index].codePointAt(0) - right[index].codePointAt(0); if (difference) return difference; }
12	  return left.length - right.length;
13	}
14	
15	function canonicalJson(value) {
16	  if (value === null || typeof value !== "object") return JSON.stringify(value);
17	  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
18	  return `{${Object.keys(value).sort(compareCodePoint).map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(",")}}`;
19	}
20	
21	function inline(value) {
22	  return value.replace(/[\r\n]+/g, " ").replace(/([\\`*_[\]<>])/g, "\\$1");
23	}
24	
25	function recordBytes(answer) {
26	  const encoded = Buffer.from(canonicalJson(answer), "utf8").toString("base64url");
27	  const checks = answer.checks.map((check) => {
28	    const evidence = check.evidence.length ? check.evidence.map((item) => `${item.authority}: ${item.reference}`).join("; ") : "no cited evidence";
29	    return `- ${inline(check.name)}: ${check.outcome} — ${inline(evidence)}`;
30	  });
31	  const unknowns = answer.unknowns.length ? answer.unknowns.map((item) => inline(item)).join("; ") : "none";
32	  return [
33	    `${RECORD_PREFIX}${encoded} -->`,
34	    `### ${inline(answer.cardId)} — ${answer.verdict}`,
35	    "",
36	    inline(answer.summary),
37	    "",
