66	export async function readJsonFile(path, logicalPath = path) {
67	  const bytes = await readFile(path);
68	  const text = canonicalText(bytes, logicalPath);
69	  let value;
70	  try {
71	    value = JSON.parse(text);
72	  } catch (error) {
73	    fail("JSON_INVALID", `${logicalPath} is not valid JSON: ${error.message}`, "Correct the canonical JSON source.");
74	  }
75	  assertNoDuplicateJsonKeys(text, logicalPath);
76	  return { value, text, bytes: Buffer.from(text, "utf8") };
77	}
78	
79	function assertNoDuplicateJsonKeys(text, logicalPath) {
80	  let index = 0;
81	  const whitespace = () => { while (/\s/u.test(text[index] ?? "")) index += 1; };
82	  const string = () => {
83	    const start = index;
84	    index += 1;
85	    while (index < text.length) {
86	      if (text[index] === "\\") { index += 2; continue; }
87	      if (text[index] === '"') { index += 1; return JSON.parse(text.slice(start, index)); }
88	      index += 1;
89	    }
90	    return "";
91	  };
92	  const value = () => {
93	    whitespace();
94	    if (text[index] === "{") {
95	      index += 1; whitespace();
96	      const keys = new Set();
97	      while (text[index] !== "}") {
98	        const key = string();
99	        if (keys.has(key)) fail("JSON_KEY_COLLISION", `${logicalPath} repeats object key ${JSON.stringify(key)}.`, "Keep each canonical JSON key exactly once.");
100	        keys.add(key); whitespace(); index += 1; value(); whitespace();
101	        if (text[index] === ",") { index += 1; whitespace(); } else break;
102	      }
103	      index += 1; return;
104	    }
105	    if (text[index] === "[") {
106	      index += 1; whitespace();
107	      while (text[index] !== "]") { value(); whitespace(); if (text[index] === ",") { index += 1; whitespace(); } else break; }
108	      index += 1; return;
109	    }
110	    if (text[index] === '"') { string(); return; }
111	    while (index < text.length && !/[\s,}\]]/u.test(text[index])) index += 1;
112	  };
113	  value();
114	}
115	
116	async function readContract(name) {
117	  return (await readJsonFile(resolve(repositoryRoot, "contracts", name), `contracts/${name}`)).value;
118	}
119	
120	function assertSchema(value, schema, label) {
121	  const errors = validateJsonSchema(value, schema);
122	  if (errors.length) fail("SCHEMA_INVALID", `${label} violates its closed schema.`, "Correct the canonical source fields.", errors);
123	}
124	
125	export async function loadSourceGraph(manifestPath) {
126	  const { manifestReal, rootReal } = await sourceRootFor(manifestPath);
127	  const manifestRead = await readJsonFile(manifestReal, relative(rootReal, manifestReal).replaceAll("\\", "/"));
128	  if (manifestRead.value?.schemaVersion !== 1) fail("UNSUPPORTED_VERSION", "The source package schemaVersion is not supported.", "Use source package schemaVersion 1.");
129	  assertSchema(manifestRead.value, await readContract("source-package.schema.json"), "source package");
130	  const manifest = manifestRead.value;
131	  assertNoCaseFoldCollisions(Object.keys(manifest.modules), "module IDs");
132	  assertNoCaseFoldCollisions(Object.keys(manifest.targets), "target aliases");
133	
134	  const modules = new Map();
135	  const sourcePathSpellings = [];
136	  for (const [id, sourcePath] of Object.entries(manifest.modules).sort(([a], [b]) => compareCodePoint(a, b))) {
137	    const resolved = await resolveContainedFile(rootReal, sourcePath, `module ${id}`);
138	    const text = canonicalText(await readFile(resolved.physical), resolved.normalized);
139	    modules.set(id, { id, path: resolved.normalized, physical: resolved.physical, text, bytes: Buffer.from(text, "utf8") });
140	    sourcePathSpellings.push(resolved.normalized);
141	  }
142	
143	  const targetSchema = await readContract("target.schema.json");
144	  const targets = new Map();
145	  for (const [alias, targetPath] of Object.entries(manifest.targets).sort(([a], [b]) => compareCodePoint(a, b))) {
146	    const resolvedTarget = await resolveContainedFile(rootReal, targetPath, `target ${alias}`);
147	    const targetRead = await readJsonFile(resolvedTarget.physical, resolvedTarget.normalized);
148	    if (targetRead.value?.schemaVersion !== 1) fail("UNSUPPORTED_VERSION", `Target ${alias} uses an unsupported schemaVersion.`, "Use target schemaVersion 1.");
149	    assertSchema(targetRead.value, targetSchema, `target ${alias}`);
