    "packet": "Absent. No packet.json in source or generated tree; packet=null in generated config.",
    "fallback": "Absent. No fallbackModule; fallbackReference=null in generated config.",
    "semanticDurableState": "None added. The only durable artifact is pilot/brief.md itself (the deliverable); the exchange directory is the pre-existing generic coordination mechanism, unchanged.",
    "autoMerge": "None. Renderer replaces only its own managed region; record fails closed on INPUT_STALE, OUTPUT_CONFLICT, MANAGED_REGION_INVALID, and OUTPUT_BUSY instead of merging.",
    "multiOutputTransactions": "None. Exactly one declaredOutput (pilot/brief.md)."
  },
