      "observed": "status BUILT, treeSha256 c10b24adb31756acd93426c5fb4bc9b1282e5981e048c9525b7f28e204e8d36f"
    },
    {
      "check": "double-build determinism",
      "command": "same build into a scratch directory (removed afterwards)",
      "observed": "identical treeSha256 c10b24adb31756acd93426c5fb4bc9b1282e5981e048c9525b7f28e204e8d36f (deterministic bytes)"
    },
    {
      "check": "artifact integrity and source currentness (separate judgments)",
      "command": "node src/core/cli.mjs check --source ... --target natural-language-pilot-product-next --out fixture/dist-product",
      "observed": "artifactIntact=true, sourceCurrent=true"
    },
    {
      "check": "source-graph inspection of the new node",
      "command": "node src/core/cli.mjs inspect --source ... --id natural-language-pilot-product-next --json",
      "observed": "renderer=targets/product/renderer.mjs, contract=targets/product/contracts/semantic-answer.product.schema.json, observer=null, declaredInputs=[pilot/product-request.md], declaredOutput=pilot/brief.md"
    },
    {
      "check": "generated diff and receipt inspection",
      "command": "file listing of fixture/dist-product; read .skill-rails-build.json and config/target.json; read generated SKILL.md header",
      "observed": "15 artifacts, exact source rows named in receipt, generated marker present, packet/observer/fallbackReference all null"
    },
    {
      "check": "installed-target integrity",
      "command": "node fixture/dist-product/scripts/run.mjs check",
      "observed": "ARTIFACT_INTACT with matching treeSha256"
    },
    {
      "check": "mechanism smoke: bootstrap record in a scratch project (created under fixture/, removed afterwards; the real pilot/ was not touched)",
      "command": "run.mjs initialize --project <scratch>; fill answer.json; run.mjs record --exchange <exchange> (twice)",
      "observed": "RECORD_INITIALIZED with input state present; first record APPLIED sha256 ddf13d475b0ba20b70f2c18a532bcb3e5b760d7103205af8287b14e7e8440d54 with effect {authority: observed, operation: file-reread} scoped to the scratch project only; second record APPLIED_ALREADY with effect none; rendered brief contained the verbatim phrase 'save once, retrieve exactly', the HTTPS-only boundary, and all three unknowns"
    },
    {
      "check": "mechanism smoke: managed-region replacement with user-owned bytes outside the region",
      "command": "append a user line after the region; initialize again; record a revised answer",
      "observed": "APPLIED sha256 3492b8cc849fc2e38ae58c30380c048344535fe0537413e3da4d4038c4349e62; region replaced, user-owned suffix byte-identical"
    }
  ],
  "unknowns": {
    "domain": [
      "Storage location: undecided in pilot/product-request.md and left unknown everywhere (contract requires an unknowns field; nothing in source resolves it).",
      "Retention period: undecided and left unknown.",
      "Import support: undecided and left unknown."
    ],
    "process": [
      "Whether one brief per project remains sufficient, or a future request class needs multiple briefs; deferred until observed."
    ]
  },
  "unprovenAndNotClaimed": [
    "Fresh unfamiliar-AI behavior: the smoke flow was driven by this authoring session, not a clean agent reading only the generated SKILL.md; behavior evidence is therefore unproven.",
    "Real effect on the user's pilot: pilot/brief.md was intentionally not produced; the observed file effect existed only in a scratch project that has been removed. No fresh use or real-pilot effect is claimed.",
    "Semantic quality guarantees: build, integrity, and schema checks prove delivery and structure only; verbatim preservation, unknown completeness, and scope fidelity remain AI meaning judgments not proven by any structural check.",
    "Unexercised mechanism paths: CRLF-managed-region re-rendering, concurrent-record lock contention, and INPUT_STALE/OUTPUT_CONFLICT recovery were not exercised in the smoke and remain unproven."
  ]
}

